ST.xhtml:p:
RTrigger(CLK := g_biHGTECHAvoidCheck);(*切割开始就开始监测*)

IF RTrigger.Q THEN
  g_boHGTECHCheckDone := FALSE;
  nCheckState := 10;
END_IF;

CASE nCheckState OF
  0:
    nCheckState := 0;
  10:(*如果下个轮廓在卡盘托架安全范围内，直接报警暂停，暂停后会自动上抬，如果下一个在安全范围之后，Z轴上抬并压零位,否则继续切割*)
    dNextNearestPoint := g_fNextNearestPointM - g_diYWorkCoordinate + g_diYMachineCoordinate;(*下一个轮廓的最近点机械坐标*)
    dNextFasterPoint := g_fNextFasterPointM - g_diYWorkCoordinate + g_diYMachineCoordinate;(*下一个轮廓的最远点机械坐标*)
    IF dNextFasterPoint >= (g_dHGTechDDAxisPosInY-g_dHGTechRearChuckSafeDis) AND dNextFasterPoint <= (g_dHGTechDDAxisPosInY+g_dHGTechRearChuckSafeDis) OR
      dNextNearestPoint >= (g_dHGTechDDAxisPosInY-g_dHGTechRearChuckSafeDis) AND dNextNearestPoint <= (g_dHGTechDDAxisPosInY+g_dHGTechRearChuckSafeDis) THEN
      g_boHGTECHCheckDone := FALSE;
      g_bHGTECHCheckWarn := TRUE;
    ELSE
      g_boHGTECHCheckDone := TRUE;
      nCheckState := 0;
    END_IF;
  20:(*上抬*)
    g_bHGTECHAvoidOpen:=TRUE;
    nCheckState := 30;
  30: (**)
    IF g_bHGTECHAvoidDone THEN
      (*IF g_diYMachineCoordinate >(g_dHGTechDDAxisPosInY+g_dHGTechRearChuckSafeDis) THEN *)
        g_boHGTECHCheckDone := TRUE;
        nCheckState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  g_boHGTECHCheckDone := FALSE;
  g_bHGTECHCheckWarn := FALSE;
  nCheckState := 0;
END_IF;
